from vlb_traj import Session
from VLABench.utils.utils import euler_to_quaternion
import numpy as np

def status(s):
    try: return s.status()
    except Exception as e: return {'success':False,'error':repr(e)}
def move_line(s,start,end,q,grip=(0,0),spacing=.012):
    start=np.array(start,float); end=np.array(end,float)
    n=max(1,int(np.ceil(np.linalg.norm(end-start)/spacing)))
    for p in np.linspace(start,end,n+1)[1:]:
        ik=s.ik(p,q)
        if not ik['success']:
            print('IK_FAIL',p.tolist()); return False
        s.step(list(ik['joint_positions'])+list(grip))
        st=status(s)
        if st.get('success'):
            print('NATIVE_SUCCESS_DURING_MOVE'); return True
    return True
s=Session(); s.record_start()
try:
    obj=np.array(s.state()['entities']['bbq_sauce']['position'],float)
    qpick=np.array(euler_to_quaternion(np.pi,0,-np.pi/2),float)
    print('pick',s.skill('pick',target_entity_name='bbq_sauce',target_pos=(obj+[0,0,.045]).tolist(),target_quat=qpick.tolist(),target_velocity=.02,max_n_substep=4)['stage_success'])
    print('lift',s.skill('lift',lift_height=.08,gripper_state=[0,0])['stage_success'])
    st=s.state(); tcp=np.array(st['robot']['tcp_position'],float); q=np.array(st['robot']['tcp_quaternion_wxyz'],float); ob=np.array(st['entities']['bbq_sauce']['position'],float); pan=np.array(st['entities']['pan_seen']['position'],float); off=tcp-ob
    if not move_line(s,tcp,tcp+[0,0,.12],q): raise RuntimeError('lift IK failed')
    high=np.array([pan[0],pan[1],1.04])+off
    if not move_line(s,s.state()['robot']['tcp_position'],high,q): raise RuntimeError('translate IK failed')
    target=np.array([pan[0],pan[1],.94])+off
    if not move_line(s,s.state()['robot']['tcp_position'],target,q): raise RuntimeError('lower IK failed')
    st=s.state(); ob=np.array(st['entities']['bbq_sauce']['position'],float); qnow=np.array(st['robot']['tcp_quaternion_wxyz'],float)
    print('placed',ob.tolist(),st['entities']['bbq_sauce']['quaternion_wxyz'],status(s))
    side=ob+np.array([.045,0,.055])
    if not move_line(s,np.array(st['robot']['tcp_position']),side,qnow,grip=(.04,.04),spacing=.01): raise RuntimeError('side IK failed')
    if not status(s).get('success'):
        st=s.state(); tcp=np.array(st['robot']['tcp_position'],float)
        print('at_side',tcp.tolist(),st['entities']['bbq_sauce']['position'])
        move_line(s,tcp,tcp+np.array([-.025,.012,0]),qnow,grip=(.04,.04),spacing=.004)
except Exception as e:
    print('CONTROL_EXCEPTION',repr(e))
print('FINAL_STATUS',status(s))
try:
    actions=s.record_stop(); print('ACTIONS',actions.shape)
    if status(s).get('success'):
        s.save_trajectory(actions,'/app/output/trajectory.npz'); print('SUCCESS SAVED')
    else: print('NATIVE SUCCESS FALSE; NOT SAVED')
except Exception as e:
    print('SUBMISSION_ERROR',repr(e))
